parameters.jsCode:
// ---------------------------------------------------------
// Generic GitHub Event Normalizer
// Supports:
//  - pull_request
//  - push
//  - issues
//  - release
//  - unknown events
// ---------------------------------------------------------

const payload = $json.body || {};
const headers = $json.headers || {};
const validationErrors = [];
// Detect GitHub Event
const eventType =
  headers["x-github-event"] ||
  headers["X-GitHub-Event"] ||
  "unknown";

// Common Repository Information
const repository =
  payload.repository?.name || "";

const owner =
  payload.repository?.owner?.login ||
  payload.repository?.owner?.name ||
  "";

const sender =
  payload.sender?.login ||
  payload.sender?.name ||
  "unknown";

// Default normalized object
const eventData = {
  eventType,
  action: payload.action || "N/A",

  repository,
  owner,
  sender,

  isValid: true,
  validationErrors
};

// ---------------------------------------------------------
// Pull Request Event
// ---------------------------------------------------------
if (eventType === "pull_request") {

  const pr = payload.pull_request || {};

  Object.assign(eventData, {

    prNumber: pr.number ?? null,

    title: (pr.title || "").trim(),

    body: (pr.body || "").trim(),

    author:
      pr.user?.login || "unknown",

    baseBranch:
      pr.base?.ref || "",

    headBranch:
      pr.head?.ref || "",

    draft:
      pr.draft ?? false,

    diffUrl:
      pr.diff_url || "",

    htmlUrl:
      pr.html_url || "",

    changedFiles:
      pr.changed_files ?? 0,

    additions:
      pr.additions ?? 0,

    deletions:
      pr.deletions ?? 0
  });

  if (!eventData.title)
    validationErrors.push("PR title is empty");

  if (!eventData.baseBranch)
    validationErrors.push("Base branch missing");

  if (!eventData.headBranch)
    validationErrors.push("Head branch missing");

  if (eventData.prNumber === null)
    validationErrors.push("PR number missing");
}

// ---------------------------------------------------------
// Push Event
// ---------------------------------------------------------
else if (eventType === "push") {

  Object.assign(eventData, {

    branch:
      payload.ref?.replace("refs/heads/", "") || "",

    before:
      payload.before || "",

    after:
      payload.after || "",

    commitCount:
      payload.commits?.length || 0,

    commits:
      payload.commits || [],

    headCommitMessage:
      payload.head_commit?.message || "",

    headCommitId:
      payload.head_commit?.id || "",

    pusher:
      payload.pusher?.name || "",

    compareUrl:
      payload.compare || ""
  });

  if (!eventData.branch)
    validationErrors.push("Branch missing");

  if (eventData.commitCount === 0)
    validationErrors.push("No commits found");
}

// ---------------------------------------------------------
// Issues Event
// ---------------------------------------------------------
else if (eventType === "issues") {

  const issue = payload.issue || {};

  Object.assign(eventData, {

    issueNumber:
      issue.number ?? null,

    title:
      issue.title || "",

    body:
      issue.body || "",

    state:
      issue.state || "",

    htmlUrl:
      issue.html_url || ""
  });

  if (!eventData.title)
    validationErrors.push("Issue title missing");
}

// ---------------------------------------------------------
// Release Event
// ---------------------------------------------------------
else if (eventType === "release") {

  const release = payload.release || {};

  Object.assign(eventData, {

    tag:
      release.tag_name || "",

    releaseName:
      release.name || "",

    draft:
      release.draft ?? false,

    prerelease:
      release.prerelease ?? false,

    htmlUrl:
      release.html_url || ""
  });

  if (!eventData.tag)
    validationErrors.push("Release tag missing");
}

// ---------------------------------------------------------
// Unknown Event
// ---------------------------------------------------------
else {

  Object.assign(eventData, {
    rawPayload: payload
  });

  eventData.validationErrors.push(
    `Unsupported GitHub event: ${eventType}`
  );
}

// ---------------------------------------------------------
// Common Validation
// ---------------------------------------------------------

if (!repository) {
  validationErrors.push("Repository missing");
}

if (!owner) {
  validationErrors.push("Repository owner missing");
}

eventData.isValid =
  validationErrors.length === 0;

// ---------------------------------------------------------
// Return Normalized Event
// ---------------------------------------------------------

return [{
  json: eventData
}];

// Static / heuristic checks on the PR.
// Replace this block with a real call to ESLint/SonarQube/etc. (HTTP Request node)
// if you want an actual static analysis engine instead of these heuristics.
const data = $json;
const staticIssues = [];

if (!data.isValid) {
  staticIssues.push(...data.validationErrors);
}

if (data.changedFiles !== null && data.changedFiles > 50) {
  staticIssues.push(`PR touches ${data.changedFiles} files - request smaller, focused PRs`);
}

const totalLines = (data.additions || 0) + (data.deletions || 0);
if (totalLines > 1000) {
  staticIssues.push(`PR changes ${totalLines} lines - consider splitting it up`);
}

if (/\b(TODO|FIXME)\b/i.test(data.body)) {
  staticIssues.push('PR description contains unresolved TODO/FIXME markers');
}

return [{
  json: {
    ...data,
    staticValidationPassed: staticIssues.length === 0,
    staticIssues
  }
}];

