// Parse the AI Agent's JSON response, tolerant of accidental code fences
const raw = ($json.output || $json.text || $json.response || '').toString().trim();
const cleaned = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```\s*$/, '').trim();

let review;
try {
  review = JSON.parse(cleaned);
} catch (e) {
  review = {
    summary: cleaned,
    riskLevel: 'UNKNOWN',
    strengths: [],
    concerns: [],
    suggestedNextSteps: []
  };
}

return [{
  json: {
    //prNumber: $('Static Code Validation').first().json.prNumber,
    commitid: $('Log Event').first().json.commit_id,
    title: $('Static Code Validation').first().json.title,
    author: $('Log Event').first().json.author,
    htmlUrl: $('Static Code Validation').first().json.htmlUrl,
    aiSummary: review.summary,
    aiRiskLevel: review.riskLevel,
    aiStrengths: review.strengths,
    aiConcerns: review.concerns,
    aiNextSteps: review.suggestedNextSteps,
    reviewedAt: new Date().toISOString()
  }
}];

